/* Local prototype interactions only. No form is sent and no API can mutate data. */
const theme=document.body.dataset.theme;
const cartKey=`usbstock.prototype.${theme}.selection`;
const escapeText=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let memory=[];
function readCart(){try{const value=JSON.parse(sessionStorage.getItem(cartKey)||'[]');return Array.isArray(value)?value.filter(x=>Number.isInteger(x.quantity)&&x.quantity>=50&&x.quantity<=x.stock&&/^\d+$/.test(String(x.id))&&/^\d+$/.test(String(x.photo))).slice(0,50):[];}catch{return memory;}}
function storeCart(items){memory=items;try{sessionStorage.setItem(cartKey,JSON.stringify(items));}catch{}updateCount();}
function updateCount(){document.querySelectorAll('[data-cart-count]').forEach(el=>el.textContent=String(readCart().length));}
function notify(message){const el=document.querySelector('.toast');if(!el)return;el.textContent=message;el.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.hidden=true,4500);}
updateCount();
if(matchMedia('(max-width:600px)').matches)document.querySelector('.filters')?.removeAttribute('open');
document.querySelector('.mobile-menu')?.addEventListener('click',event=>{const button=event.currentTarget;const nav=document.getElementById('mobile-nav');nav.hidden=!nav.hidden;button.setAttribute('aria-expanded',String(!nav.hidden));button.setAttribute('aria-label',nav.hidden?'Abrir navegación':'Cerrar navegación');});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){const nav=document.getElementById('mobile-nav');if(nav&&!nav.hidden){nav.hidden=true;const button=document.querySelector('.mobile-menu');button.setAttribute('aria-expanded','false');button.focus();}}});
let opener;
function openDialog(dialog,source){opener=source;dialog.showModal();(dialog.querySelector('input')||dialog.querySelector('[data-close]'))?.focus();}
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>dialog.close()));dialog.addEventListener('close',()=>opener?.focus());});
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const items=[...dialog.querySelectorAll('a[href],button,input,select,textarea,[tabindex]')].filter(el=>!el.disabled&&el.tabIndex>=0&&el.getClientRects().length);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}));
document.querySelector('[data-product-form]')?.addEventListener('change',event=>{if(event.target.name==='color')document.querySelector('[data-color-label]').textContent=event.target.value;});
document.querySelector('[data-product-form]')?.addEventListener('submit',event=>{
 event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;
 const fields=new FormData(form);const quantity=Number(fields.get('quantity'));const stock=Number(form.dataset.stock);if(!Number.isInteger(quantity)||quantity<50||quantity>stock)return;
 const item={id:Number(form.dataset.productId),name:form.dataset.name,photo:form.dataset.photo,stock,capacity:fields.get('capacity'),color:fields.get('color'),quantity};
 const cart=readCart();const old=cart.findIndex(x=>x.id===item.id&&x.capacity===item.capacity&&x.color===item.color);if(old>=0)cart[old]=item;else{if(cart.length>=50){notify('La selección admite hasta 50 variantes.');return;}cart.push(item);}storeCart(cart);
 document.querySelector('[data-added-message]').textContent=`${item.name} · ${item.capacity} GB · ${item.color} · ${quantity} piezas.`;
 openDialog(document.getElementById('added-dialog'),event.submitter);
});
function renderSelection(){const target=document.querySelector('[data-selection]');if(!target)return;const items=readCart();document.querySelector('[data-selection-count]').textContent=`${items.length} variantes`;if(!items.length){target.innerHTML=`<div class="empty"><h3>Aquí empieza tu proyecto.</h3><p>Agrega al menos una variante desde el catálogo.</p><a class="button secondary" href="/${theme}/catalogo">Explorar modelos →</a></div>`;return;}
 target.innerHTML=items.map((item,index)=>`<article class="selection-item"><img src="/assets/${item.photo}.jpg" alt="${escapeText(item.name)}" width="72" height="85"><div><h3>${escapeText(item.name)}</h3><p>${escapeText(item.capacity)} GB · ${escapeText(item.color)} · Demostración</p><div class="selection-actions"><label for="cart-qty-${index}">Cantidad</label><input id="cart-qty-${index}" data-cart-quantity="${index}" type="number" value="${item.quantity}" min="50" max="${item.stock}" required><button type="button" data-remove="${index}" aria-label="Quitar ${escapeText(item.name)}">Quitar</button></div></div></article>`).join('')+`<div class="selection-total"><strong>${items.reduce((sum,x)=>sum+x.quantity,0).toLocaleString('es-MX')} piezas</strong><span>Precio por cotizar</span></div>`;
 target.querySelectorAll('[data-remove]').forEach(button=>button.addEventListener('click',()=>{const cart=readCart();cart.splice(Number(button.dataset.remove),1);storeCart(cart);renderSelection();notify('Variante retirada de la selección demo.');document.querySelector('[data-selection] a, [data-selection] input')?.focus();}));
 target.querySelectorAll('[data-cart-quantity]').forEach(input=>input.addEventListener('change',()=>{if(!input.reportValidity())return;const cart=readCart();cart[Number(input.dataset.cartQuantity)].quantity=Number(input.value);storeCart(cart);target.querySelector('.selection-total strong').textContent=`${cart.reduce((sum,x)=>sum+x.quantity,0).toLocaleString('es-MX')} piezas`;}));
}
renderSelection();
document.querySelector('[data-request-form]')?.addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;const error=document.querySelector('[data-request-error]');if(!readCart().length){error.textContent='Agrega al menos una variante antes de continuar.';error.hidden=false;return;}const quantities=[...document.querySelectorAll('[data-cart-quantity]')];if(!quantities.every(input=>input.reportValidity())){error.textContent='Revisa las cantidades de tu selección.';error.hidden=false;return;}if(!form.reportValidity())return;form.hidden=true;document.querySelector('[data-request-success]').hidden=false;document.querySelector('[data-request-success]').setAttribute('tabindex','-1');document.querySelector('[data-request-success]').focus();});
function filterTable(){const q=(document.querySelector('[data-table-search]')?.value||'').toLowerCase();const status=document.querySelector('[data-table-status]')?.value;let count=0;document.querySelectorAll('[data-table-row]').forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(q)||Boolean(status&&row.dataset.status!==status);if(!row.hidden)count++;});const empty=document.querySelector('[data-table-empty]');if(empty)empty.hidden=count!==0;}
document.querySelector('[data-table-search]')?.addEventListener('input',filterTable);document.querySelector('[data-table-status]')?.addEventListener('change',filterTable);
let editing;
document.querySelectorAll('[data-edit]').forEach(button=>button.addEventListener('click',()=>{editing=button;document.getElementById('edit-name').value=button.dataset.edit;document.getElementById('edit-description').value=button.dataset.description;document.getElementById('edit-visible').checked=button.closest('tr').dataset.status==='publicado';document.querySelector('[data-edit-model]').textContent=button.dataset.model;openDialog(document.getElementById('edit-dialog'),button);}));
document.querySelector('[data-edit-form]')?.addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const value=document.getElementById('edit-name').value;const row=editing.closest('tr');row.querySelector('.table-product strong').textContent=value;editing.dataset.edit=value;editing.dataset.description=document.getElementById('edit-description').value;const published=document.getElementById('edit-visible').checked;row.dataset.status=published?'publicado':'pendiente';const badge=row.querySelector('.badge');badge.className='badge '+(published?'green':'warning');badge.textContent=published?form.dataset.readyLabel:form.dataset.pendingLabel;document.getElementById('edit-dialog').close();filterTable();if(row.hidden)document.querySelector('[data-table-search]').focus();notify('Cambio guardado solo en esta vista de demostración.');});
document.querySelector('[data-demo-settings]')?.addEventListener('submit',event=>{event.preventDefault();if(!event.currentTarget.reportValidity())return;document.body.classList.toggle('density-compact',document.getElementById('view-density').value==='Compacta');document.querySelector('.workspace-label').textContent=document.getElementById('space-name').value;notify('Preferencia aplicada solo a esta vista de demostración.');});
